'use client';

import { useId, useState } from 'react';
import './star-rating-fill.css';

export interface StarRatingFillProps {
  value: number;
  onChange: (value: number) => void;
  /** The question, used as the group's legend. */
  label: string;
  max?: number;
  className?: string;
}

/**
 * A radio group drawn as stars. Hovering previews a rating with outlined,
 * dashed stars; choosing one fills them solid with a small pop. Arrow keys
 * work as in any radio group.
 */
export function StarRatingFill({
  value,
  onChange,
  label,
  max = 5,
  className = '',
}: StarRatingFillProps) {
  const [preview, setPreview] = useState<number | null>(null);
  const [popped, setPopped] = useState(0);
  const name = useId();
  const shown = preview ?? value;

  return (
    <fieldset
      className={`mg-stars ${className}`}
      onPointerLeave={() => setPreview(null)}
    >
      <legend className='mg-stars__legend'>{label}</legend>
      <div className='mg-stars__row'>
        {Array.from({ length: max }, (_, i) => i + 1).map((n) => {
          const previewing = preview !== null && preview !== value;
          const state = n > shown ? 'empty' : previewing ? 'preview' : 'set';
          return (
            <label
              key={n}
              className='mg-stars__star'
              data-state={state}
              data-pop={n <= value && popped === value}
              onPointerEnter={() => setPreview(n)}
            >
              <input
                type='radio'
                className='mg-stars__input'
                name={name}
                value={n}
                checked={value === n}
                onChange={() => {
                  onChange(n);
                  setPopped(n);
                }}
              />
              <svg viewBox='0 0 24 24' aria-hidden='true'>
                <path d='M12 2.8l2.8 5.9 6.4.8-4.7 4.4 1.2 6.4L12 17.2l-5.7 3.1 1.2-6.4-4.7-4.4 6.4-.8z' />
              </svg>
              <span className='mg-stars__sr'>
                {n} {n === 1 ? 'star' : 'stars'}
              </span>
            </label>
          );
        })}
      </div>
      <p className='mg-stars__text'>
        {preview !== null && preview !== value
          ? `Preview: ${preview} of ${max}`
          : value
            ? `Your rating: ${value} of ${max}`
            : 'Not rated yet'}
      </p>
    </fieldset>
  );
}

.mg-stars {
  margin: 0;
  padding: 0;
  border: 0;
  color: var(--mg-ink, #0c1738);
}

.mg-stars__legend {
  margin-bottom: 6px;
  padding: 0;
  font-weight: 700;
}

.mg-stars__row {
  display: flex;
  gap: 2px;
}

.mg-stars__star {
  position: relative;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  cursor: pointer;
}

.mg-stars__input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.mg-stars__star svg {
  width: 32px;
  height: 32px;
  fill: #fff;
  stroke: #8a96bd;
  stroke-width: 1.5;
  stroke-linejoin: round;
  transition:
    fill 160ms ease,
    stroke 160ms ease,
    transform 160ms ease;
}

/* Preview: outlined and dashed, so it differs from a real rating by shape. */
.mg-stars__star[data-state='preview'] svg {
  fill: #e6ecff;
  stroke: var(--mg-accent, #164cff);
  stroke-dasharray: 3 2;
  transform: scale(1.06);
}

.mg-stars__star[data-state='set'] svg {
  fill: var(--mg-accent, #164cff);
  stroke: var(--mg-ink, #0c1738);
}

.mg-stars__star[data-pop='true'] svg {
  animation: mg-stars-pop 320ms cubic-bezier(0.3, 1.7, 0.5, 1);
}

.mg-stars__input:focus-visible + svg {
  outline: 3px solid var(--mg-accent, #164cff);
  outline-offset: 3px;
  border-radius: 6px;
}

.mg-stars__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

.mg-stars__text {
  margin: 6px 0 0;
  color: #46527a;
  font-size: 13px;
}

@keyframes mg-stars-pop {
  50% {
    transform: scale(1.3);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-stars__star svg {
    transition: none;
  }
  .mg-stars__star[data-pop='true'] svg {
    animation: none;
  }
}
